-- Add print permissions without rewriting applied role seeds or custom merchant roles.
UPDATE mch_role SET perms=JSON_ARRAY_APPEND(perms,'$','biz:print:read'),updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE entity_no='*' AND builtin=1 AND role_code='MANAGER' AND deleted=0 AND JSON_CONTAINS(perms,JSON_QUOTE('biz:print:read'))=0;
